source("R/platform-load.R",encoding="UTF-8");brohn_load(ui=TRUE)
local({
  n<-0L;check<-function(ok,label){if(!isTRUE(ok))stop(label);n<<-n+1L;cat("PASS",label,"\n")};reject<-function(x)inherits(try(force(x),silent=TRUE),"try-error")
  folder<-tempfile("brohn-maxdiff-materials-");dir.create(folder);store<-brohn_open_store(file.path(folder,"source"));other<-brohn_open_store(file.path(folder,"destination"));on.exit({brohn_close_store(store);brohn_close_store(other)},add=TRUE);brohn_initialise_library(store);brohn_initialise_library(other)
  first<-normalizePath("examples/stimuli/sample-design-a.png",winslash="/");second<-normalizePath("examples/stimuli/sample-design-b.png",winslash="/")
  d<-brohn_new_design("Original illustrated best-worst study","survey");d$instructions<-"";d$questions<-list();d$maxdiff<-list(brohn_maxdiff_new("Original best-worst material",id="md-original"));legacy<-brohn_json(d);protocol<-brohn_json(brohn_compile(d,2L))
  brohn_validate_design(d);check(identical(legacy,brohn_json(d))&&identical(protocol,brohn_json(brohn_compile(d,2L)))&&all(vapply(d$maxdiff[[1]]$items,function(i)identical(names(i),c("id","label")),logical(1))),"Absent item illustration leaves legacy fields and compiled source unchanged")
  original<-d;d<-brohn_material_attach_png(store,d,"maxdiff_item","item-1","md-original",path=first,image_alt="Original first illustration <literal>")
  d<-brohn_material_attach_png(store,d,"maxdiff_item","item-2","md-original",path=first,image_alt="Second description for identical bytes")
  d<-brohn_material_attach_png(store,d,"maxdiff_item","item-4","md-original",path=second,image_alt="Original fourth illustration")
  check(brohn_hash(d)!=brohn_hash(original)&&brohn_hash(d$maxdiff[[1]])!=brohn_hash(original$maxdiff[[1]])&&!"illustration"%in%names(d$maxdiff[[1]]$items[[3]]),"Mixed text/image items change exact source identity without adding fields to text-only owners")
  target<-brohn_material_target(d,"maxdiff_item","item-1","md-original");check(identical(target$owner,d$maxdiff[[1]])&&target$stage=="Tasks","Material authority pins the full owning exercise, including set membership and settings")
  order<-function(x,i)lapply(brohn_maxdiff_compile(x,i)$trials,function(t)t[c("set_id","position","item_order")])
  check(all(vapply(1:6,function(i)identical(brohn_json(order(original$maxdiff[[1]],i)),brohn_json(order(d$maxdiff[[1]],i))),logical(1))),"Adding images preserves exact seeded set and item orders across six allocations")
  check(length(brohn_illustration_profile(d)$assets)==2L&&brohn_illustration_profile(d)$pixels==960000,"Shared item bytes decode once while owner descriptions remain distinct")
  restored<-d;for(id in c("item-1","item-2","item-4"))restored<-brohn_remove_maxdiff_illustration(restored,"md-original",id)
  check(identical(brohn_json(restored),legacy),"Removing item illustrations restores all original labels, sets and procedure settings")
  check(reject(brohn_material_use_text(d,"maxdiff_item","item-1","md-original",text="Overwrite label")),"Passive text conversion cannot rewrite a MaxDiff item label")
  changed<-brohn_material_describe(d,"maxdiff_item","item-1","md-original",image_alt="Revised exact description");check(identical(changed$maxdiff[[1]]$items[[1]]$illustration$asset,d$maxdiff[[1]]$items[[1]]$illustration$asset)&&identical(changed$maxdiff[[1]]$sets,d$maxdiff[[1]]$sets),"Description change preserves exact bytes and offered sets")
  bad<-d$maxdiff[[1]];bad$items[[1]]$illustration<-NULL;bad$items[[1]]["illustration"]<-list(NULL);check(reject(brohn_maxdiff_validate(bad)),"Explicit null illustration is rejected rather than silently converted to absence")
  bad<-d$maxdiff[[1]];bad$items[[1]]$illustration$image_alt<-"";check(reject(brohn_maxdiff_validate(bad)),"Present MaxDiff illustration requires authored nonempty alt")
  d$questions<-list(brohn_question("Original combined image","text","end","q-combined"));d<-brohn_material_attach_png(store,d,"question","q-combined",path=first,image_alt="Question description")
  check(length(brohn_illustration_profile(d)$assets)==2L&&brohn_illustration_profile(d)$pixels==960000,"Question and choice owners share the same unique-image budget")
  bounds<-d;bounds$maxdiff[[1]]$items<-lapply(1:9,function(i)list(id=paste0("item-",i),label=paste("Original",i),illustration=list(asset=modifyList(d$maxdiff[[1]]$items[[1]]$illustration$asset,list(hash=sprintf("%064d",i),width=4000,height=2000)),image_alt="Original bounded image")))
  check(reject(brohn_validate_design(bounds)),"Complete design validation applies the shared decoded budget to MaxDiff items")
  assigned<-brohn_compile(d,2L);transport<-.brohn_delivery_protocol_urls(assigned,strrep("a",64));steps<-Filter(function(s)s$type=="maxdiff",transport$timeline)
  check(identical(assigned$design,transport$design)&&all(vapply(steps,function(s)identical(s$choice,Filter(function(t)t$id==s$id,assigned$timeline)[[1]]$choice)&&all(vapply(Filter(function(i)!is.null(i$illustration),s$choice$items),function(i)grepl(i$illustration$asset$hash,s$item_image_urls[[i$id]],fixed=TRUE),logical(1))),logical(1))),"Item transport URLs remain outside canonical choice objects and frozen design")
  saved<-brohn_put_entity(store,"study",d$id,d);release<-brohn_publish(store,d$id,"sample");app<-brohn_delivery_app(store);get<-function(hash)app$call(list(PATH_INFO=paste0("/api/assets/",release$token,"/",hash),REQUEST_METHOD="GET"))
  hash<-d$maxdiff[[1]]$items[[1]]$illustration$asset$hash;check(get(hash)$status==200L&&digest::digest(file=get(hash)$body$file,algo="sha256")==hash,"Actual release serves exact permitted MaxDiff image bytes")
  clone<-brohn_clone_study(store,d$id);template<-brohn_save_template(store,d$id);reuse<-brohn_use_template(store,template$id)
  check(identical(brohn_json(clone$body$maxdiff[[1]]$items[[1]]$illustration),brohn_json(d$maxdiff[[1]]$items[[1]]$illustration))&&identical(brohn_json(reuse$body$maxdiff[[1]]$items[[2]]$illustration),brohn_json(d$maxdiff[[1]]$items[[2]]$illustration)),"Clone and template preserve item-specific image descriptions while remapping graph IDs")
  zip<-brohn_export_design(store,d$id,file.path(folder,"original-choice-images.brohn-study.zip"));imported<-brohn_import_design(other,zip)
  check(identical(brohn_json(imported$body$maxdiff[[1]]$items[[1]]$illustration),brohn_json(d$maxdiff[[1]]$items[[1]]$illustration))&&file.exists(brohn_object_path(other,hash)),"Cross-workspace ZIP preserves exact MaxDiff bytes and illustration metadata")
  partial<-file.path(folder,"partial.png");writeBin(readBin(first,"raw",n=40L),partial);broken<-d;broken$id<-brohn_id("study");broken$maxdiff[[1]]$items[[1]]$illustration$asset<-c(brohn_store_object(store,path=partial,media_type="image/png"),list(filename="partial.png",width=800,height=600));brohn_put_entity(store,"study",broken$id,broken)
  check(reject(brohn_publish(store,broken$id,"sample")),"MaxDiff publication completely decodes PNG instead of trusting its header")
  broken_zip<-brohn_export_design(store,broken$id,file.path(folder,"broken-choice-images.brohn-study.zip"));before<-length(brohn_studies(other));check(reject(brohn_import_design(other,broken_zip))&&length(brohn_studies(other))==before,"Corrupt MaxDiff illustration is rejected before portable catalog registration")
  base<-original$maxdiff[[1]];base$items<-base$items[1:3];base$sets<-list(list(id="all-three",item_ids=as.list(brohn_ids(base$items))));illustrated<-base;illustrated$items[[1]]$illustration<-d$maxdiff[[1]]$items[[1]]$illustration
  pairs<-list(c(1,2),c(1,3),c(2,1),c(2,3),c(3,1),c(3,2));counts<-c(8,16,2,8,1,2);rows<-list();for(i in seq_along(pairs))for(j in seq_len(counts[[i]])){k<-length(rows)+1L;rows[[k]]<-list(id=paste0("response-",k),participant_id="original-person",participant_linkage=TRUE,session_id="original-session",exposure_id=paste0("exposure-",k),design_hash=brohn_hash(base),set_id="all-three",item_order=base$sets[[1]]$item_ids,presented=TRUE,status="answered",best_id=paste0("item-",pairs[[i]][[1]]),worst_id=paste0("item-",pairs[[i]][[2]]),missing_reason=NULL)}
  check(reject(brohn_maxdiff_analysis(illustrated,rows)),"Old response hash cannot be reused against newly illustrated exercise")
  rebound<-lapply(rows,function(r){r$design_hash<-brohn_hash(illustrated);r});plain<-brohn_maxdiff_analysis(base,rows);result<-brohn_maxdiff_analysis(illustrated,rebound)
  check(identical(plain$items,result$items)&&identical(plain$model,result$model)&&max(abs(vapply(result$model$utilities,`[[`,numeric(1),"utility")-c(log(2),0,-log(2))))<1e-6,"Explicitly rebound37-pair oracle retains identical counts, paired likelihood and sum-zero utilities")
  source<-list(hash=strrep("a",64),origin="sample",id="original-choice-ledger",revision=1L);plain<-brohn_maxdiff_analysis(base,rows,source);csv<-file.path(folder,"original-source-responses.csv");brohn_export_report_csv(list(analysis=list(choice_tasks=list(plain))),csv);table<-brohn_read_table(csv,"csv",20000L)
  metadata<-list(exercise_id=base$id,origin_statement="Original synthetic paired reference",participant_column="participant_id",session_column="session_id",exposure_column="exposure_id",design_hash_column="design_hash",set_column="set_id",item_order_column="item_order",presented_column="presented",status_column="status",best_column="best_id",worst_column="worst_id",missing_reason_column="missing_reason",participant_linkage_column="participant_linkage",exercise_column="exercise_id",origin_column="origin")
  target<-original;target$maxdiff<-list(illustrated);check(reject(brohn_import_maxdiff_analysis(table,metadata,target,source)),"Actual old-source CSV cannot be imported against a newly illustrated exercise hash")
  cat("PASS",n,"MaxDiff illustration domain checks\n")
})
